 async function samples(progress,limit=3,dense=false){await pose(progress);return page.$eval('.nw-motion-dialog iframe',(f,{limit,dense})=>{const d=f.contentDocument,m=window.NAGWEB_STREAM_MODEL,ns=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),clip=ns[0].__nwMotionClip,c=d.querySelector('.nw-mosaic-marquee-surface'),host=ns[0].offsetParent,k=c.width/host.clientWidth,tiles=ns.flatMap((n,slot)=>(n.__nwMotionInstances||[]).map(t=>({t,id:n.dataset.id,slot}))).sort((a,b)=>b.t.depth-a.t.depth),out=[],seen=new Set(),uvs=dense?Array.from({length:121},(_,i)=>[.2+(i%11)*.06,.2+Math.floor(i/11)*.06]):[[.5,.5],[.3,.3],[.7,.3],[.3,.7],[.7,.7],[.5,.2],[.5,.8]];
 for(const q of tiles)for(const [u,v] of uvs){const p=m.meshPoint(q.t.mesh,u,v);if(!p)continue;const x=(Math.floor(p.x*k)+.5)/k,y=(Math.floor(p.y*k)+.5)/k;if(x<clip.left+8||x>clip.left+clip.width-8||y<clip.top+8||y>clip.top+clip.height-8||seen.has(x+','+y))continue;const hits=[];let stable=true;for(const z of tiles){const hit=!!m.meshUV(z.t.mesh,x,y);if([[x-4,y],[x+4,y],[x,y-4],[x,y+4]].some(([a,b])=>!!m.meshUV(z.t.mesh,a,b)!==hit)){stable=false;break;}if(hit)hits.push(z);}if(!stable||!hits.some(z=>z.t.alpha>.05))continue;seen.add(x+','+y);out.push({x,y,id:hits.find(z=>z.t.alpha>.05).id,hits:hits.map(z=>({slot:z.slot,alpha:z.t.alpha,depth:z.t.depth,layoutKind:z.t.layoutKind})),pixel:Array.from(c.getContext('2d').getImageData(Math.floor(x*k),Math.floor(y*k),1,1).data)});if(out.length>=limit)return out;}return out;},{limit,dense});}
 function expected(point,alpha){let a=0,rgb=[0,0,0];for(const hit of [...point.hits].reverse()){const v=Math.round(alpha*255)/255*hit.alpha,c=[[255,0,0],[0,255,0],[0,0,255],[255,255,0]][hit.slot%4];rgb=rgb.map((x,i)=>c[i]*v+x*(1-v));a=v+a*(1-v);}return[...rgb.map(x=>a?x/a:0),a*255];}
 function checkPixel(point,alpha,context){const e=expected(point,alpha);for(let i=0;i<4;i++)assert.ok(Math.abs(point.pixel[i]-e[i])<(i===3?6:10),JSON.stringify({context,point,expected:e,alpha}));}

