  await change('[data-motion-stream="cornerRadius"]','12');await colors();await pose(0);const corner=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,m=window.NAGWEB_STREAM_MODEL,ns=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),clip=ns[0].__nwMotionClip,tiles=ns.flatMap(n=>n.__nwMotionInstances);for(const t of tiles)for(const [u,v] of [[.005,.005],[.995,.005],[.005,.995],[.995,.995]]){const p=m.meshPoint(t.mesh,u,v);if(!p||p.x<clip.left+8||p.x>clip.left+clip.width-8||p.y<clip.top+8||p.y>clip.top+clip.height-8)continue;if(!tiles.some(z=>m.meshUV(z.mesh,p.x,p.y)))return p;}return null;});assert.ok(corner,'Empty rounded marquee corner');assert.ok((await at(corner.x,corner.y))[3]<8);await clickPoint(corner.x,corner.y,null);
