  const reuse=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,clock=f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id];for(let i=0;i<20;i++)clock.set(i/20);const native=d.createElement;let created=0;d.createElement=function(...a){if(a[0]==='canvas')created++;return native.apply(this,a);};try{for(let i=0;i<20;i++)clock.set(i/20);return{created,bounded:Array.from(d.querySelectorAll('canvas')).every(c=>c.width<=2048&&c.height<=2048)};}finally{d.createElement=native;}});assert.equal(reuse.created,0);assert.equal(reuse.bounded,true);console.log('Mosaic Marquee pixels: three mixed-size masonry layouts, both small and large viewer-facing planes, wide/tall surfaces, empty stacked gaps and optional nonselectable shadows, native picking, rounded corners, plane compositing and zero warmed canvas allocations OK');
